-- Релізи від програм засмічували хронологію продукту («Реліз <хеш>» на кожен деплой) — прибираємо; самі події лишаються в product_events
DELETE FROM product_items WHERE kind = 'log' AND title LIKE 'Реліз %';
INSERT INTO changelog (title, body, created_at) VALUES ('Хронологія продукту без сміття', 'Прибрав із хронології продуктів записи «Реліз <код>» — програма слала їх на кожен деплой, і вони засмічували історію. Релізи тепер видно тільки в продукті → «Звʼязок» → «Події». Хронологія — це етапи з витяжок і оновлень (Оновлення 1, 2, …). Коли етапів багато (понад 9) — показуються вертикальною стрічкою по днях, від нових до старих, а не змійкою.', datetime('now'));

INSERT INTO changelog (title, body, created_at) VALUES ('Оновлення продукту знову розбираються', 'Витяжка «ОНОВЛЕННЯ» падала, коли модель віддавала списки замість тексту — тепер усе зводиться до тексту і записується. Якщо щось не так — замість «спробуй ще раз» видно справжню причину.', datetime('now'));
